    :root {
      --bg: #f6f8fb;
      --surface: #ffffff;
      --surface-soft: #f9fbff;
      --text: #0b1220;
      --muted: #5c667a;
      --line: #dce4f1;
      --accent: #1f6fff;
      --accent-soft: #e9f0ff;
