      --maxw: 1180px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      background: linear-gradient(180deg, #f8faff 0%, #f6f8fb 200px, #f6f8fb 100%);
      color: var(--text);
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--maxw), calc(100% - 40px));
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      backdrop-filter: blur(10px);
      background: rgba(248, 250, 255, 0.92);
      border-bottom: 1px solid rgba(220, 228, 241, 0.9);
      z-index: 40;
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 72px;
      gap: 20px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 750;
      letter-spacing: -0.02em;
    }

    .brand-mark {
      width: 28px;
      height: 28px;
      border-radius: 8px;
