      background: #eef3ff;
      outline: none;
    }

    .caret {
      font-size: 11px;
      color: var(--muted);
    }

    .mega {
      position: absolute;
      top: calc(100% + 10px);
      left: 0;
      min-width: 560px;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 14px;
      box-shadow: var(--shadow);
      padding: 18px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-6px);
      transition: all 0.2s ease;
      pointer-events: none;
