    ];

    const latestPosts = [
      { category: 'Engineering', date: 'February 12, 2026', title: 'A new programming model for durable execution', excerpt: 'Durable primitives and event replay patterns that simplify reliability in distributed applications.', author: 'Rafa Ortega', initials: 'RO' },
      { category: 'Security', date: 'February 9, 2026', title: 'Zero Data Retention on AI Gateway', excerpt: 'How DeployCloud ships strict data controls for sensitive model traffic with enterprise-grade defaults.', author: 'Nina Brooks', initials: 'NB' },
      { category: 'Engineering', date: 'February 2, 2026', title: 'Optimizing Sandbox snapshots', excerpt: 'Snapshot-level improvements reduce cold starts and improve parity across local, CI, and preview environments.', author: 'Iris Chen', initials: 'IC' },
      { category: 'Customers', date: 'January 26, 2026', title: 'How a startup made a blog platform work for humans and AI alike', excerpt: 'A customer story about balancing editorial quality, machine readability, and lightning-fast publish workflows.', author: 'Devon Price', initials: 'DP' },
      { category: 'Engineering', date: 'January 20, 2026', title: 'Making build tool 96% faster with agents, sandboxes, and humans', excerpt: 'A deep dive into cache strategy, parallel execution, and human review loops that transformed build performance.', author: 'Maya Lin', initials: 'ML' },
