    const featuredGrid = document.getElementById('featured-grid');
    const newsGrid = document.getElementById('news-grid');
    const noResults = document.getElementById('no-results');
    const showMoreBtn = document.getElementById('show-more-btn');
    const searchInput = document.getElementById('post-search');
    const pills = [...document.querySelectorAll('.pill')];

    let activeCategory = 'All Posts';
    let searchQuery = '';
    const batchSize = 6;
    let visibleCount = batchSize;

    function renderFeatured() {
      featuredGrid.innerHTML = featuredPosts.map((post) => {
        const stats = post.stats ? `<div class="stats">${post.stats.map((s) => `<div class="stat">${s}</div>`).join('')}</div>` : '';
        return `
          <article class="featured-card">
            <span class="tag">${post.category}</span>
            <div class="meta">${post.date}</div>
            <h3>${post.title}</h3>
            <p class="excerpt">${post.excerpt}</p>
            ${stats}
            <div class="author"><span class="avatar">${post.initials}</span>${post.author}</div>
          </article>
        `;
      }).join('');
    }

    function cardTemplate(post) {
      return `
        <article class="news-card" data-category="${post.category}">
          <span class="tag">${post.category}</span>
          <div class="meta">${post.date}</div>
          <h3>${post.title}</h3>
          <p class="excerpt">${post.excerpt}</p>
          <div class="author"><span class="avatar">${post.initials}</span>${post.author}</div>
        </article>
      `;
    }

    function getFilteredPosts() {
      return latestPosts.filter((post) => {
        const categoryMatch = activeCategory === 'All Posts' || post.category === activeCategory;
        const query = searchQuery.trim().toLowerCase();
        const queryMatch = !query || [post.title, post.excerpt, post.author, post.category].join(' ').toLowerCase().includes(query);
        return categoryMatch && queryMatch;
      });
    }

    function renderNews({ resetCount = false } = {}) {
      const filtered = getFilteredPosts();
      if (resetCount) visibleCount = batchSize;

      const visiblePosts = filtered.slice(0, visibleCount);
      newsGrid.innerHTML = visiblePosts.map(cardTemplate).join('');

      noResults.style.display = filtered.length ? 'none' : 'block';
      showMoreBtn.style.display = filtered.length > visibleCount ? 'inline-flex' : 'none';
    }

    function setActivePill(category) {
      pills.forEach((pill) => {
        const isActive = pill.dataset.category === category;
        pill.classList.toggle('active', isActive);
        pill.setAttribute('aria-selected', isActive ? 'true' : 'false');
      });
    }

    pills.forEach((pill) => {
      pill.addEventListener('click', () => {
        activeCategory = pill.dataset.category;
        setActivePill(activeCategory);
        renderNews({ resetCount: true });
      });
    });

    searchInput.addEventListener('input', (event) => {
      searchQuery = event.target.value;
      renderNews({ resetCount: true });
    });

    showMoreBtn.addEventListener('click', () => {
      visibleCount += batchSize;
      renderNews();
    });

    const menuToggles = [...document.querySelectorAll('[data-menu-toggle]')];
    const menus = {
      products: document.getElementById('products-menu'),
      resources: document.getElementById('resources-menu')
    };

    function closeMenus(except = null) {
      menuToggles.forEach((btn) => {
        const menuName = btn.dataset.menuToggle;
        const isOpen = menuName === except;
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        menus[menuName].classList.toggle('open', isOpen);
      });
    }

    menuToggles.forEach((btn) => {
      const menuName = btn.dataset.menuToggle;
      const openMenu = () => closeMenus(menuName);
      btn.addEventListener('mouseenter', openMenu);
      btn.parentElement.addEventListener('mouseenter', openMenu);
      btn.addEventListener('click', (event) => {
        event.stopPropagation();
        const expanded = btn.getAttribute('aria-expanded') === 'true';
        closeMenus(expanded ? null : menuName);
      });
    });

    document.addEventListener('click', () => closeMenus(null));
    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') closeMenus(null);
    });

    renderFeatured();
    renderNews();
  </script>
